	CONSTRAINT "iq_actions_idempotency_unique" UNIQUE("org_id","idempotency_key"),
	CONSTRAINT "iq_actions_tier_check" CHECK ("iq_actions"."tier" IN ('A0', 'A1', 'A2', 'A3')),
	CONSTRAINT "iq_actions_mode_check" CHECK ("iq_actions"."mode" IN ('AUTO', 'APPROVAL', 'HANDOFF')),
	CONSTRAINT "iq_actions_status_check" CHECK ("iq_actions"."status" IN ('QUEUED', 'PENDING_APPROVAL', 'APPROVED', 'EXECUTING', 'SUCCEEDED', 'FAILED', 'REJECTED', 'EXPIRED', 'SUPERSEDED', 'CANCELLED', 'UNDONE', 'HANDOFF', 'UNDOING', 'UNDO_FAILED')),
	CONSTRAINT "iq_actions_kind_tier_check" CHECK ("iq_actions"."tier" = 'A3' OR ("iq_actions"."action_kind", "iq_actions"."tier") IN (('brief.publish', 'A0'), ('detection.publish', 'A0'), ('forecast.publish', 'A0'), ('reconciliation.report', 'A0'), ('purchase_order.create_draft', 'A1'), ('inventory.flag_recount', 'A1'), ('prep_list.prefill', 'A1'), ('task.open_internal', 'A1'), ('menu.mark_86', 'A2'), ('customer.winback_message', 'A2'))),
	CONSTRAINT "iq_actions_tier_mode_check" CHECK (("iq_actions"."tier" = 'A0' AND "iq_actions"."mode" = 'AUTO')
          OR ("iq_actions"."tier" = 'A1' AND "iq_actions"."mode" IN ('AUTO', 'APPROVAL'))
          OR ("iq_actions"."tier" = 'A2' AND "iq_actions"."mode" = 'APPROVAL')
          OR ("iq_actions"."tier" = 'A3' AND "iq_actions"."mode" = 'HANDOFF')),
	CONSTRAINT "iq_actions_mode_status_check" CHECK (("iq_actions"."mode" = 'AUTO' AND "iq_actions"."status" IN ('QUEUED', 'EXECUTING', 'SUCCEEDED', 'FAILED', 'CANCELLED', 'UNDOING', 'UNDONE', 'UNDO_FAILED'))
          OR ("iq_actions"."mode" = 'APPROVAL' AND "iq_actions"."status" IN ('PENDING_APPROVAL', 'APPROVED', 'EXECUTING', 'SUCCEEDED', 'FAILED', 'REJECTED', 'EXPIRED', 'SUPERSEDED', 'CANCELLED', 'UNDOING', 'UNDONE', 'UNDO_FAILED'))
