	CONSTRAINT "iq_auto_policies_version_check" CHECK ("iq_auto_policies"."version" >= 1),
	CONSTRAINT "iq_auto_policies_limits_check" CHECK (CASE WHEN jsonb_typeof("iq_auto_policies"."limits") = 'object'
