-- A referenced insight is frozen. Once a recommendation cites an insight —
-- as its own RECOMMENDATION row or through payload.evidenceInsightIds — what
-- it claimed cannot be rewritten underneath the decision; a changed claim is
-- a new row that supersedes it. status, superseded_by and expires_at stay
-- writable so that superseding and expiry still work.
CREATE FUNCTION public.iq_insights_freeze_referenced()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF OLD.referenced_at IS NOT NULL AND (
       NEW.referenced_at IS DISTINCT FROM OLD.referenced_at
    OR NEW.org_id IS DISTINCT FROM OLD.org_id
    OR NEW.location_id IS DISTINCT FROM OLD.location_id
    OR NEW.claim_type IS DISTINCT FROM OLD.claim_type
    OR NEW.schema_version IS DISTINCT FROM OLD.schema_version
    OR NEW.subject_kind IS DISTINCT FROM OLD.subject_kind
    OR NEW.subject_ref IS DISTINCT FROM OLD.subject_ref
    OR NEW.period_start IS DISTINCT FROM OLD.period_start
    OR NEW.period_end IS DISTINCT FROM OLD.period_end
    OR NEW.dedupe_key IS DISTINCT FROM OLD.dedupe_key
    OR NEW.payload IS DISTINCT FROM OLD.payload
    OR NEW.evidence IS DISTINCT FROM OLD.evidence
    OR NEW.content_hash IS DISTINCT FROM OLD.content_hash
  ) THEN
    RAISE EXCEPTION 'iq_insights %: referenced insights are frozen; supersede with a new row', OLD.id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER iq_insights_freeze_referenced_trigger
BEFORE UPDATE ON public.iq_insights
FOR EACH ROW EXECUTE FUNCTION public.iq_insights_freeze_referenced();
--> statement-breakpoint
-- Marks the cited insights referenced in the same transaction as the
-- recommendation, so no repository can forget to. The recommendation's own
-- insight must be a RECOMMENDATION claim; its evidence ids are frozen too,
-- within the same org only.
CREATE FUNCTION public.iq_recommendations_reference_insights()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  claim text;
  cited jsonb;
BEGIN
  SELECT claim_type, payload -> 'evidenceInsightIds' INTO claim, cited
  FROM iq_insights
  WHERE id = NEW.insight_id AND org_id = NEW.org_id;

  IF claim IS DISTINCT FROM 'RECOMMENDATION' THEN
    RAISE EXCEPTION 'iq_recommendations %: insight % is not a RECOMMENDATION of this org', NEW.id, NEW.insight_id
      USING ERRCODE = '23514';
  END IF;

  UPDATE iq_insights
  SET referenced_at = now()
  WHERE org_id = NEW.org_id
    AND referenced_at IS NULL
    AND (
      id = NEW.insight_id
      OR (jsonb_typeof(cited) = 'array'
          AND id::text IN (SELECT jsonb_array_elements_text(cited)))
    );
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER iq_recommendations_reference_insights_trigger
AFTER INSERT OR UPDATE OF insight_id ON public.iq_recommendations
FOR EACH ROW EXECUTE FUNCTION public.iq_recommendations_reference_insights();
--> statement-breakpoint
-- iq_actions.status_changed_at is database time, never the caller's clock
-- (RELIABILITY C6): the cooldown and stale-row sweeps read it.
CREATE FUNCTION public.iq_actions_stamp_status_change()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN
    NEW.status_changed_at := now();
  ELSE
    NEW.status_changed_at := OLD.status_changed_at;
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER iq_actions_stamp_status_change_trigger
BEFORE INSERT OR UPDATE ON public.iq_actions
FOR EACH ROW EXECUTE FUNCTION public.iq_actions_stamp_status_change();
--> statement-breakpoint
-- RLS and grants. 0033 stopped anon/authenticated getting INSERT, UPDATE,
-- DELETE and TRUNCATE on new tables, but Supabase's defaults still hand them
-- SELECT, REFERENCES and TRIGGER — so every iq_* table starts from REVOKE ALL.
-- Staff (OWNER, ADMIN, MANAGER) may read insights, recommendations and
-- actions of their own org; the rest are server-only: RLS on, no policy, no
-- grant. Nothing is writable except by postgres (the app), which bypasses RLS.
DO $$
DECLARE
  target text;
BEGIN
  FOREACH target IN ARRAY ARRAY[
    'iq_job_runs', 'iq_insights', 'iq_forecasts', 'iq_recommendations',
    'iq_actions', 'iq_outcomes', 'iq_auto_policies'
  ] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', target);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', target);
    EXECUTE format('REVOKE ALL ON TABLE %I FROM PUBLIC, anon, authenticated', target);
  END LOOP;

  FOREACH target IN ARRAY ARRAY['iq_insights', 'iq_recommendations', 'iq_actions'] LOOP
    EXECUTE format(
      'CREATE POLICY %I ON %I FOR SELECT TO authenticated
         USING (auth_has_role(org_id, ARRAY[''OWNER'', ''ADMIN'', ''MANAGER'']))',
      target || '_staff_read', target
    );
    EXECUTE format('GRANT SELECT ON TABLE %I TO authenticated', target);
  END LOOP;
END $$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.iq_insights_freeze_referenced() FROM PUBLIC, anon, authenticated;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.iq_recommendations_reference_insights() FROM PUBLIC, anon, authenticated;
--> statement-breakpoint
REVOKE ALL ON FUNCTION public.iq_actions_stamp_status_change() FROM PUBLIC, anon, authenticated;
